    44|  } catch (e: any) {
    45|    // Ignore error if column already exists
    46|  }
    47|
    48|  // Auth Routes
    49|  app.post("/api/auth/signup", async (req, res) => {
    50|    const { username, email, password, geminiKey } = req.body;
    51|    if (!username || !email || !password) {
    52|      return res.status(400).json({ error: "Missing required fields" });
    53|    }
    54|    try {
    55|      const id = `user-${Date.now()}`;
    56|      const hashedPassword = await bcrypt.hash(password, 10);
