    58|        "INSERT INTO users (id, username, email, password, geminiKey) VALUES (?, ?, ?, ?, ?)",
    59|        [id, username, email, hashedPassword, geminiKey || null]
    60|      );
    61|      res.json({ id, username, email, geminiKey: geminiKey || null, notificationPrefs: {} });
    62|    } catch (error: any) {
    63|      if (error.message.includes("UNIQUE constraint failed")) {
    64|        return res.status(409).json({ error: "Email already exists" });
    65|      }
