    80|      );
    81|      
    82|      if (user && await bcrypt.compare(password, user.hashedPassword)) {
    83|        const { hashedPassword, ...userWithoutPassword } = user;
    84|        res.json({ ...userWithoutPassword, notificationPrefs: {} });
    85|      } else {
