    97|    try {
    98|      await db.run("UPDATE users SET geminiKey = ? WHERE id = ?", [geminiKey, id]);
    99|      res.json({ success: true });
   100|    } catch (error) {
   101|      console.error("Failed to update Gemini key:", error);
   102|      res.status(500).json({ error: "Failed to update Gemini key" });
   103|    }
   104|  });
   105|
   106|  // API Routes
