   108|    const { userId } = req.query;
   109|    try {
   110|      let rows;
   111|      if (userId) {
   112|        rows = await db.all("SELECT data FROM projects WHERE ownerId = ?", [userId]);
   113|      } else {
   114|        rows = await db.all("SELECT data FROM projects");
   115|      }
