   122|  });
   123|
   124|  app.post("/api/projects", async (req, res) => {
   125|    try {
   126|      const projects = req.body; // Expecting an array of projects to sync
   127|      if (!Array.isArray(projects)) {
   128|        return res.status(400).json({ error: "Expected an array of projects" });
   129|      }
   130|      for (const project of projects) {
   131|        await db.run(
   132|          "INSERT OR REPLACE INTO projects (id, ownerId, data) VALUES (?, ?, ?)",
