   160|        await db.run("DELETE FROM projects");
   161|      }
   162|      res.json({ success: true });
   163|    } catch (error) {
   164|      console.error("Failed to delete projects:", error);
   165|      res.status(500).json({ error: "Failed to delete projects" });
   166|    }
   167|  });
   168|
   169|  // Serve help.md and other root static files for modals
