{"content": "     1|import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
     2|import { TEMPLATES } from '../constants/projectData';
     3|
     4|interface CommandPaletteProps {
     5|    isOpen: boolean;
     6|    onClose: () => void;
     7|    onNavigate: (action: string) => void;
     8|}
     9|
    10|interface Command {
    11|    id: string;
    12|    label: string;
    13|    description: string;
    14|    action: string;
    15|    category: 'navigation' | 'discipline' | 'quick';
    16|    icon?: string;
    17|}
    18|
    19|const NAV_COMMANDS: Command[] = [
    20|    { id: 'nav-new', label: 'New Project', description: 'Create a new project workspace', action: 'new-project', category: 'navigation', icon: '✨' },
    21|    { id: 'nav-dashboard', label: 'Go to Dashboard', description: 'Return to the main dashboard', action: 'dashboard', category: 'navigation', icon: '📊' },
    22|    { id: 'nav-help', label: 'Open Help', description: 'View help documentation', action: 'help', category: 'navigation', icon: '❓' },
    23|    { id: 'nav-logout', label: 'Logout', description: 'Sign out of your account', action: 'logout', category: 'navigation', icon: '🚪' },
    24|];
    25|
    26|const QUICK_COMMANDS: Command[] = [
    27|    { id: 'quick-mobile', label: '⚡ Quick: Mobile App', description: 'Set up a mobile app project with defaults', action: 'quick-mobile-app-dev', category: 'quick', icon: '📱' },
    28|    { id: 'quick-software', label: '⚡ Quick: Software Dev', description: 'Set up an agile software project', action: 'quick-software-dev', category: 'quick', icon: '💻' },
    29|    { id: 'quick-marketing', label: '⚡ Quick: Marketing', description: 'Set up a marketing campaign', action: 'quick-marketing-campaign', category: 'quick', icon: '📣' },
    30|    { id: 'quick-ai', label: '⚡ Quick: AI Integration', description: 'Set up an AI integration project', action: 'quick-ai-integration', category: 'quick', icon: '🤖' },
    31|];
    32|
    33|export const CommandPalette: React.FC<CommandPaletteProps> = ({ isOpen, onClose, onNavigate }) => {
    34|    const [query, setQuery] = useState('');
    35|    const [selectedIndex, setSelectedIndex] = useState(0);
    36|    const inputRef = useRef<HTMLInputElement>(null);
    37|    const listRef = useRef<HTMLDivElement>(null);
    38|
    39|    // Build discipline commands from templates
    40|    const disciplineCommands: Command[] = useMemo(() => 
    41|        TEMPLATES.map(t => ({
    42|            id: `disc-${t.id}`,
    43|            label: t.name,
    44|            description: `Discipline: ${t.discipline}`,
    45|            action: `select-template-${t.id}`,
    46|            category: 'discipline' as const,
    47|            icon: '📋',
    48|        })), []
    49|    );
    50|
    51|    // Filter commands based on query
    52|    const filteredCommands = useMemo(() => {
    53|        if (!query.trim()) return [...NAV_COMMANDS, ...QUICK_COMMANDS, ...disciplineCommands.slice(0, 10)];
    54|        
    55|        const q = query.toLowerCase();
    56|        const all = [...NAV_COMMANDS, ...QUICK_COMMANDS, ...disciplineCommands];
    57|        return all.filter(cmd => 
    58|            cmd.label.toLowerCase().includes(q) || 
    59|            cmd.description.toLowerCase().includes(q) ||
    60|            cmd.category.toLowerCase().includes(q)
    61|        ).slice(0, 20); // Limit results
    62|    }, [query, disciplineCommands]);
    63|
    64|    // Reset selection when filter changes
    65|    useEffect(() => {
    66|        setSelectedIndex(0);
    67|    }, [query]);
    68|
    69|    // Focus input when opened
    70|    useEffect(() => {
    71|        if (isOpen) {
    72|            setTimeout(() => inputRef.current?.focus(), 50);
    73|            setQuery('');
    74|            setSelectedIndex(0);
    75|        }
    76|    }, [isOpen]);
    77|
    78|    const executeCommand = useCallback((cmd: Command) => {
    79|        onClose();
    80|        onNavigate(cmd.action);
    81|    }, [onClose, onNavigate]);
    82|
    83|    // Keyboard navigation
    84|    const handleKeyDown = (e: React.KeyboardEvent) => {
    85|        switch (e.key) {
    86|            case 'ArrowDown':
    87|                e.preventDefault();
    88|                setSelectedIndex(prev => Math.min(prev + 1, filteredCommands.length - 1));
    89|                break;
    90|            case 'ArrowUp':
    91|                e.preventDefault();
    92|                setSelectedIndex(prev => Math.max(prev - 1, 0));
    93|                break;
    94|            case 'Enter':
    95|                e.preventDefault();
    96|                if (filteredCommands[selectedIndex]) {
    97|                    executeCommand(filteredCommands[selectedIndex]);
    98|                }
    99|                break;
   100|            case 'Escape':
   101|                e.preventDefault();
   102|                onClose();
   103|                break;
   104|        }
   105|    };
   106|
   107|    // Scroll selected item into view
   108|    useEffect(() => {
   109|        if (listRef.current) {
   110|            const el = listRef.current.children[selectedIndex] as HTMLElement;
   111|            if (el) el.scrollIntoView({ block: 'nearest' });
   112|        }
   113|    }, [selectedIndex]);
   114|
   115|    if (!isOpen) return null;
   116|
   117|    // Group results
   118|    const groupedResults = useMemo(() => {
   119|        const groups: Record<string, Command[]> = {};
   120|        const cmds = filteredCommands as Command[];
   121|        cmds.forEach(cmd => {
   122|            if (!groups[cmd.category]) groups[cmd.category] = [];
   123|            groups[cmd.category].push(cmd);
   124|        });
   125|        return groups;
   126|    }, [filteredCommands]);
   127|
   128|    const categoryLabels: Record<string, string> = {
   129|        navigation: 'Navigation',
   130|        discipline: 'Disciplines',
   131|        quick: 'Quick Setup',
   132|    };
   133|
   134|    const categoryIcons: Record<string, string> = {
   135|        navigation: '🔀',
   136|        discipline: '📋',
   137|        quick: '⚡',
   138|    };
   139|
   140|    let idx = 0;
   141|
   142|    return (
   143|        <div 
   144|            className="modal-overlay" 
   145|            onClick={onClose}
   146|            style={{ zIndex: 2000, alignItems: 'flex-start', paddingTop: '15vh' }}
   147|        >
   148|            <div 
   149|                className="glass-card"
   150|                onClick={(e) => e.stopPropagation()}
   151|                style={{
   152|                    maxWidth: '600px', width: '100%', padding: '0',
   153|                    boxShadow: '0 25px 60px rgba(0,0,0,0.5), 0 0 40px rgba(99,102,241,0.1)',
   154|                    border: '1px solid rgba(99,102,241,0.3)',
   155|                    overflow: 'hidden',
   156|                    animation: 'modal-in 0.2s ease'
   157|                }}
   158|            >
   159|                {/* Search Input */}
   160|                <div style={{ 
   161|                    padding: '1rem 1.25rem', 
   162|                    borderBottom: '1px solid var(--card-border)',
   163|                    display: 'flex', alignItems: 'center', gap: '0.75rem'
   164|                }}>
   165|                    <span style={{ fontSize: '1.2rem', color: 'var(--secondary-text)' }}>⌘</span>
   166|                    <input
   167|                        ref={inputRef}
   168|                        type="text"
   169|                        value={query}
   170|                        onChange={(e) => setQuery(e.target.value)}
   171|                        onKeyDown={handleKeyDown}
   172|                        placeholder="Search commands, disciplines, or projects..."
   173|                        style={{
   174|                            border: 'none', background: 'transparent', padding: '0.5rem 0',
   175|                            fontSize: '1rem', outline: 'none', width: '100%',
   176|                            color: 'var(--primary-text)'
   177|                        }}
   178|                        autoFocus
   179|                    />
   180|                    <kbd style={{
   181|                        padding: '0.2rem 0.5rem', borderRadius: '4px',
   182|                        background: 'rgba(255,255,255,0.05)', border: '1px solid var(--card-border)',
   183|                        fontSize: '0.7rem', color: 'var(--secondary-text)'
   184|                    }}>ESC</kbd>
   185|                </div>
   186|
   187|                {/* Results */}
   188|                <div ref={listRef} style={{ maxHeight: '400px', overflowY: 'auto', padding: '0.5rem 0' }}>
   189|                    {filteredCommands.length === 0 ? (
   190|                        <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--secondary-text)' }}>
   191|                            No results found for "{query}"
   192|                        </div>
   193|                    ) : (
   194|                        Object.entries(groupedResults).map((entry: [string, Command[]]) => {
   195|                            const [category, cmds] = entry;
   196|                            return (
   197|                            <div key={category}>
   198|                                <div style={{
   199|                                    padding: '0.5rem 1.25rem 0.25rem',
   200|                                    fontSize: '0.7rem', color: 'var(--tertiary-text)',
   201|                                    textTransform: 'uppercase', letterSpacing: '0.05em', fontWeight: 700
   202|                                }}>
   203|                                    {categoryIcons[category]} {categoryLabels[category] || category}
   204|                                </div>
   205|                                {cmds.map(cmd => {
   206|                                    const currentIdx = idx++;
   207|                                    const isSelected = currentIdx === selectedIndex;
   208|                                    return (
   209|                                        <div
   210|                                            key={cmd.id}
   211|                                            onClick={() => executeCommand(cmd)}
   212|                                            style={{
   213|                                                padding: '0.6rem 1.25rem',
   214|                                                display: 'flex', alignItems: 'center', gap: '0.75rem',
   215|                                                cursor: 'pointer',
   216|                                                background: isSelected ? 'rgba(99, 102, 241, 0.15)' : 'transparent',
   217|                                                borderLeft: isSelected ? '2px solid var(--accent-color)' : '2px solid transparent',
   218|                                                transition: 'all 0.1s'
   219|                                            }}
   220|                                            onMouseEnter={() => setSelectedIndex(currentIdx)}
   221|                                        >
   222|                                            <span style={{ fontSize: '1rem', width: '24px', textAlign: 'center' }}>
   223|                                                {cmd.icon || '📋'}
   224|                                            </span>
   225|                                            <div style={{ flex: 1 }}>
   226|                                                <div style={{ fontWeight: 600, fontSize: '0.9rem', color: 'var(--primary-text)' }}>
   227|                                                    {cmd.label}
   228|                                                </div>
   229|                                                <div style={{ fontSize: '0.75rem', color: 'var(--secondary-text)' }}>
   230|                                                    {cmd.description}
   231|                                                </div>
   232|                                            </div>
   233|                                            {cmd.category === 'discipline' && (
   234|                                                <span className="chip-blue" style={{ fontSize: '0.65rem' }}>
   235|                                                    select
   236|                                                </span>
   237|                                            )}
   238|                                        </div>
   239|                                    );
   240|                                })}
   241|                            </div>
   242|                            );
   243|                        })
   244|                    )}
   245|                </div>
   246|
   247|                {/* Footer hint */}
   248|                <div style={{
   249|                    padding: '0.6rem 1.25rem',
   250|                    borderTop: '1px solid var(--card-border)',
   251|                    display: 'flex', gap: '1.5rem', fontSize: '0.7rem', color: 'var(--tertiary-text)'
   252|                }}>
   253|                    <span>↑↓ Navigate</span>
   254|                    <span>↵ Select</span>
   255|                    <span>Esc Close</span>
   256|                </div>
   257|            </div>
   258|        </div>
   259|    );
   260|};", "total_lines": 259, "file_size": 11770, "truncated": false, "is_binary": false, "is_image": false}

