     2|import React, { useState, useEffect, useRef } from 'react';
     3|import { User, Notification } from '../types';
     4|
     5|interface HeaderProps {
     6|    onNewProject: () => void;
     7|    onHomeClick: () => void;
     8|    disabled: boolean;
     9|    isLandingPage: boolean;
    10|    currentUser: User;
    11|    onLogout: () => void;
    12|    notifications: Notification[];
    13|    onNotificationClick: (notification: Notification) => void;
    14|    onMarkAllRead: () => void;
    15|    onClearAllProjects: () => void;
