  /* Reset */
  * { box-sizing: border-box; margin: 0; padding: 0; }

  /* Responsive Typography Base */
  html { font-size: 16px; }
  @media (max-width: 1200px) { html { font-size: 15px; } }
  @media (max-width: 992px) { html { font-size: 14px; } }
  @media (max-width: 768px) { html { font-size: 13px; } }

  html, body {
    min-height: 100vh;
    background-color: var(--background-color);
    color: var(--primary-text);
    font-family: 'Space Grotesk', sans-serif;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
  }

  #root {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
  }

  /* Background Effects */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: 
      radial-gradient(circle at 10% 20%, rgba(157, 0, 255, 0.12) 0%, transparent 40%),
      radial-gradient(circle at 90% 80%, rgba(0, 242, 255, 0.08) 0%, transparent 40%),
      radial-gradient(circle at 50% 50%, rgba(255, 0, 255, 0.03) 0%, transparent 60%);
    z-index: -1;
    pointer-events: none;
  }

  main {
    padding: 2rem 5%;
    flex: 1;
    width: 100%;
    max-width: 1600px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    animation: slideUp 0.8s cubic-bezier(0.16, 1, 0.3, 1);
  }

  /* Animations */
  @keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
  @keyframes spin { 100% { transform: rotate(360deg); } }
  @keyframes pulseHighlight {
    0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(0, 255, 170, 0.7); }
    70% { transform: scale(1.02); box-shadow: 0 0 15px 10px rgba(0, 255, 170, 0); }
    100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(0, 255, 170, 0); }
  }

  /* Header */
  .app-header {
    padding: 1rem 5%;
    border-bottom: 1px solid var(--border-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    min-height: 70px;
    background: rgba(2, 2, 7, 0.85);
    backdrop-filter: blur(24px);
    position: sticky;
    top: 0;
    z-index: 500;
  }

  /* Buttons */
  .button {
    padding: 0.8rem 1.6rem;
    border: 1px solid var(--glass-border);
    background: var(--glass-bg);
    color: var(--primary-text);
    border-radius: 100px;
    cursor: pointer;
    text-transform: uppercase;
    font-weight: 700;
    letter-spacing: 1px;
    transition: all 0.3s ease;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.8rem;
    font-size: 0.9rem;
    white-space: nowrap;
  }

  .button:hover:not([disabled]) { 
    background: rgba(255, 255, 255, 0.08);
    border-color: var(--accent-color);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0, 242, 255, 0.2);
  }

  .button-primary { 
    background: linear-gradient(135deg, var(--neon-purple), var(--neon-pink));
    border: none;
    box-shadow: 0 4px 15px rgba(157, 0, 255, 0.3);
  }

  .button-small { padding: 0.5rem 1rem; font-size: 0.8rem; }
  .button-large { padding: 1.2rem 2.5rem; font-size: 1.1rem; }

  .button-danger {
    background: rgba(255, 51, 102, 0.1);
    border-color: var(--error-color);
    color: var(--error-color);
  }

  /* Inputs */
  input[type="text"], input[type="password"], input[type="email"], select, textarea {
    width: 100%;
    padding: 1rem 1.5rem;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    color: var(--primary-text);
    font-family: inherit;
    font-size: 1rem;
    transition: border-color 0.2s;
