    19|async function withRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
    20|    let lastError: Error | any = new Error("Unknown error");
    21|    for (let i = 0; i < retries; i++) {
    22|        try {
    23|            return await fn();
    24|        } catch (error: any) {
    25|            lastError = error;
    26|            console.warn(`Attempt ${i + 1} failed. Retrying...`, error);
    27|            if (error?.message?.includes("API_KEY_INVALID") || error?.message?.includes("safety")) {
    28|                throw error;
    29|            }
    30|            if (i < retries - 1) {
    31|                await new Promise(res => setTimeout(res, delay * Math.pow(2, i)));
    32|            }
    33|        }
    34|    }
    35|    throw lastError;
    36|};
